```dart
import 'dart:collection';

List<String> separateParenGroups(String parenString) {
  final List<String> result = [];
  int nestLevel = 0;
  String currentGroup = '';

  for (int i = 0; i < parenString.length; i++) {
    final char = parenString[i];
    if (char == '(') {
      nestLevel++;
      if (nestLevel == 1) {
        currentGroup = '';
      }
    } else if (char == ')') {
      nestLevel--;
      if (nestLevel == 0) {
        result.add(currentGroup);
        currentGroup = '';
      }
    } else {
      if (nestLevel > 0) {
        currentGroup += char;
      }
    }
  }

  return result;
}
