List<int> parseNestedParens(String parenString) {
  int parseParenGroup(String s) {
    int depth = 0;
    int maxDepth = 0;
    for (int i = 0; i < s.length; i++) {
      String c = s[i];
      if (c == '(') {
        depth += 1;
        maxDepth = depth > maxDepth ? depth : maxDepth;
      } else {
        depth -= 1;
      }
    }
    return maxDepth;
  }

  return parenString
      .split(' ')
      .where((x) => x.isNotEmpty)
      .map((x) => parseParenGroup(x))
      .toList();
}

@pragma('vm:entry-point')
void main() {
  // Test cases
  print(parseNestedParens("(()()) ((())) () ((())()())"));
  // Expected: [2, 3, 1, 3]

  print(parseNestedParens("() (()) ((()))"));
  // Expected: [1, 2, 3]

  print(parseNestedParens(""));
  // Expected: []

  print(parseNestedParens("(((())))"));
  // Expected: [4]
}

