import 'dart:math';

int isPrime(int num) {
  if (num <= 1) return 0;
  if (num == 2) return 1;
  if (num % 2 == 0) return 0;
  int sqrtNum = sqrt(num).toInt();
  for (int i = 3; i <= sqrtNum; i += 2) {
    if (num % i == 0) return 0;
  }
  return 1;
}

int primeFib(int n) {
  if (n < 1) return -1;
  int count = 0;
  int a = 1, b = 1;
  while (true) {
    int fib = a + b;
    a = b;
    b = fib;
    if (isPrime(fib)) {
      count++;
      if (count == n) return fib;
    }
  }
}
```

