import 'dart:math';

List<String> numericalLetterGrade(List<double> grades) {
  if (grades.isEmpty) return [];

  List<String> letterGrades = [];
  double lowest = grades.reduce(min);
  double highest = grades.reduce(max);

  for (var grade in grades) {
    var normalized = (grade - lowest) / (highest - lowest);
    var percent = normalized * 100;

    String? letterGrade;
    if (percent >= 95.0 && percent <= 100.0) {
      letterGrade = 'A+';
    } else if (percent >= 90.0 && percent < 95.0) {
      letterGrade = 'A';
    } else if (percent >= 85.0 && percent < 90.0) {
      letterGrade = 'A-';
    } else if (percent >= 80.0 && percent < 85.0) {
      letterGrade = 'B+';
    } else if (percent >= 75.0 && percent < 80.0) {
      letterGrade = 'B';
    } else if (percent >= 70.0 && percent < 75.0) {
      letterGrade = 'B-';
    } else if (percent >= 65.0 && percent < 70.0) {
      letterGrade = 'C+';
    } else if (percent >= 60.0 && percent < 65.0) {
      letterGrade = 'C';
    } else if (percent >= 55.0 && percent < 60.0) {
      letterGrade = 'C-';
    } else if (percent >= 50.0 && percent < 55.0) {
      letterGrade = 'D+';
    } else if (percent >= 45.0 && percent < 50.0) {
      letterGrade = 'D';
    } else if (percent >= 40.0 && percent < 45.0) {
      letterGrade = 'D-';
    } else if (percent >= 0.0 && percent < 40.0) {
      letterGrade = 'F';
    }

    letterGrades.add(letterGrade!);
  }

  return letterGrades;
}
