int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  final cols = grid[0].length;

  // Directions for moving in the matrix (up, down, left, right)
  final directions = [(-1, 0), (1, 0), (0, -1), (0, 1)];

  // Helper function to check if a cell is within bounds and not visited yet
  bool isValid(int row, int col, Set<String> visited) {
    return row >= 0 && row < rows && col >= 0 && col < cols &&
        !visited.contains('$row,$col');
  }

  // BFS function to find maximum fill value from start position
  int bfs(int startRow, int startCol, Set<String> visited) {
    final queue = Queue<Set<String>>();
    final initialVisited = { '$startRow,$startCol' };
    queue.add(initialVisited);

    var maxVal = 0;

    while (queue.isNotEmpty) {
      final currentVisited = queue.removeFirst();
      final lastPos = currentVisited.last.split(',').map((e) => int.parse(e)).toList();

      // Check all four directions
      for (final dir in directions) {
        final newRow = lastPos[0] + dir[0];
        final newCol = lastPos[1] + dir[1];

        if (isValid(newRow, newCol, currentVisited)) {
          final newVisited = {...currentVisited};
          newVisited.add('$newRow,$newCol');

          // If we have enough space to add this cell's value, proceed
          final newValue = maxVal + grid[newRow][newCol];
          if (newValue <= capacity) {
            queue.add(newVisited);
            maxVal = newValue;
          }
        }
      }
    }

    return maxVal;
  }

  // Main algorithm using DFS with backtracking
  int dfs(int row, int col, Set<String> visited) {
    final val = grid[row][col];
    final newVal = (visited.isEmpty ? 0 : (visited.length == 1 ? val : (visited.length > 1 ? (visited.length - 1)*val : 0))) ;

    // If no more cells can be added without exceeding capacity, return
    if (newVal > capacity) return 0;

    visited.add('$row,$col');

    var maxFill = newVal;

    // Try each direction
    for (var dir in directions) {
      final newRow = row + dir[0];
      final newCol = col + dir[1];

      if (isValid(newRow, newCol, visited)) {
        final temp = dfs(newRow, newCol, visited);

        if (temp != 0) {
          maxFill += temp;
        }
      }
    }

    visited.removeLast(); // Backtrack
    return maxFill;
  }

  // Initialize visited set and call DFS starting at (0, 0)
  final visited = {};
  final result = dfs(0, 0, visited);

  return result;
}
